//! Dataset own-key snapshots retain exact native code units and actual attribute order.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><p id=target></p><svg id=svg></svg></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://dataset-inspection.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}

#[test]
fn dataset_bulk_definitions_scalar_raw_flags_undefined_and_real_native_records(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,defs={first:{value:'one',writable:false,enumerable:false,configurable:false}},watch=new MutationObserver(function(){});watch.observe(n,{attributes:true,attributeOldValue:true});defs['x\ud800Name']={value:'raw\udfff',writable:false};defs.omitted={writable:false};if(Object.defineProperties(d,defs)!==d||d.first!=='one'||d['x\ud800Name']!=='raw\udfff'||d.omitted!=='undefined')throw 'native bulk values';var names=Object.keys(d),desc=Object.getOwnPropertyDescriptor(d,'x\ud800Name'),records=watch.takeRecords();if(names.length!==3||names[1]!=='x\ud800Name'||!desc.writable||!desc.enumerable||!desc.configurable||records.length!==3||records[1].attributeName!=='data-x\ud800-name'||records[1].target!==n||records[1].oldValue!==null)throw 'native actual descriptors and observation';"#);}

#[test]
fn dataset_bulk_definitions_collects_all_descriptors_before_value_binding(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,order='',second={value:'before'},defs={};Object.defineProperty(defs,'first',{enumerable:true,get:function(){order+='A';return {value:{toString:function(){order+='V';second.value='after';return 'one';}}};}});Object.defineProperty(defs,'x\ud800',{enumerable:true,get:function(){order+='B';return second;}});Object.defineProperties(d,defs);if(order!=='ABV'||d.first!=='one'||d['x\ud800']!=='before')throw 'collected descriptor values precede native binding';"#);}

#[test]
fn dataset_bulk_definitions_collection_abrupt_keeps_only_author_effects(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,marker={},caught,defs={},watch=new MutationObserver(function(){});watch.observe(n,{attributes:true});Object.defineProperty(defs,'first',{enumerable:true,get:function(){return {value:'uncommitted'};}});Object.defineProperty(defs,'x\ud800',{enumerable:true,get:function(){d.author='effect';throw marker;}});try{Object.defineProperties(d,defs);}catch(e){caught=e;}if(caught!==marker||d.first!==undefined||d['x\ud800']!==undefined||d.author!=='effect'||watch.takeRecords().length!==1)throw 'collection before native commits and author abrupt identity';"#);}

#[test]
fn dataset_bulk_definitions_invalid_key_preserves_prior_commit_and_finishes_collection(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,defs={},order='',caught;Object.defineProperty(defs,'first',{enumerable:true,get:function(){order+='A';return {value:'one'};}});Object.defineProperty(defs,'bad\ud800-key',{enumerable:true,get:function(){order+='B';return {value:'bad'};}});Object.defineProperty(defs,'last',{enumerable:true,get:function(){order+='C';return {value:'last'};}});try{Object.defineProperties(d,defs);}catch(e){caught=e;}if(!(caught instanceof DOMException)||caught.name!=='SyntaxError'||order!=='ABC'||d.first!=='one'||d.last!==undefined||Object.keys(d).length!==1)throw 'native invalid key at application after all collection';"#);}

#[test]
fn dataset_bulk_definitions_generic_accessor_and_symbol_value_reject_after_prior_commit(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var rejected of [{},{get:function(){throw 'must not call';}},{value:Symbol('bad')}]){var n=document.createElement('p'),d=n.dataset,defs={first:{value:'one'},last:{value:'last'}},caught;delete defs.last;defs['x\ud800']=rejected;defs.last={value:'last'};try{Object.defineProperties(d,defs);}catch(e){caught=e;}if(!(caught instanceof TypeError)||d.first!=='one'||d['x\ud800']!==undefined||d.last!==undefined||Object.keys(d).length!==1)throw 'native data requirement and late value Symbol conversion';}"#);}

#[test]
fn dataset_bulk_definitions_binding_abrupt_preserves_identity_and_author_mutation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,marker={},caught,order='',defs={first:{value:'one'}},watch=new MutationObserver(function(){});watch.observe(n,{attributes:true});Object.defineProperty(defs,'x\ud800',{enumerable:true,get:function(){order+='collect';return {value:{toString:function(){order+='bind';d.side='effect';throw marker;}}};}});Object.defineProperty(defs,'last',{enumerable:true,get:function(){order+='last';return {value:'last'};}});try{Object.defineProperties(d,defs);}catch(e){caught=e;}if(caught!==marker||order!=='collectlastbind'||d.first!=='one'||d.side!=='effect'||d.last!==undefined||watch.takeRecords().length!==2)throw 'ordered binding and preserved partial native author effects';"#);}

#[test]
fn dataset_bulk_definitions_skips_hidden_and_inherited_descriptor_entries(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,proto={inherited:{value:'bad'}},defs=Object.create(proto),hits=0;Object.defineProperty(defs,'hidden',{enumerable:false,get:function(){hits++;throw 'hidden';}});defs['x\ud800']={value:'native'};Object.defineProperties(d,defs);if(hits||d.inherited!==undefined||d.hidden!==undefined||Object.keys(d).length!==1||d['x\ud800']!=='native')throw 'own enumerable descriptor entries only';for(var empty of [{},1,true,Symbol('empty')])if(Object.defineProperties(d,empty)!==d)throw 'empty boxed descriptors';"#);}

#[test]
fn dataset_bulk_definitions_html_svg_native_name_order_and_shadow_bypass(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var n of [document.getElementById('target'),document.getElementById('svg')]){var d=n.dataset,defs={},hits=0;n.setAttribute=function(){hits++;throw 'shadow';};Object.defineProperty(DOMStringMap.prototype,'x\ud800Name',{set:function(){hits++;throw 'prototype setter';},configurable:true});defs['x\ud800Name']={value:'native'};defs.next={value:'next'};Object.defineProperties(d,defs);if(hits||d['x\ud800Name']!=='native'||n.getAttributeNS(null,'data-x\ud800-name')!=='native'||Object.keys(d)[0]!=='x\ud800Name')throw 'actual native HTML SVG targets and attribute order';}"#);}

#[test]
fn dataset_bulk_definitions_copy_storage_work_deadline_refusal_is_atomic_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!(r#"var n=document.getElementById('target'),data=n.dataset,defs={{first:{{value:'{}'}}}};defs['x\ud800']={{value:'raw'}};var watch=new MutationObserver(function(){{}});watch.observe(n,{{attributes:true}});"#,"refused".repeat(200)));let limit=p.state.retained_limit;for mode in 0..4{let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.retained_limit=p.state.retained,2=>p.state.host_work=0,_=>p.state.execution_deadline=Some(Instant::now())};let error=p.runtime.execute("Object.defineProperties(data,defs);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains(["string work","retained","DOM work","computation time"][mode]),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.retained_limit=limit;p.state.execution_deadline=None;run(&mut d,&mut f,&mut p,r#"if(watch.takeRecords().length||Object.keys(data).length)throw 'refused native batch changed state';Object.defineProperties(data,{recovered:{value:'yes'}});if(data.recovered!=='yes'||watch.takeRecords().length!==1)throw 'native batch recovery';delete data.recovered;watch.takeRecords();"#);}}
